  '{"name": "羲禾科技", "industry": "semiconductor", "seg": "design", "listed": false, "round": "科创板 IPO 已过会", "valuation": 37, "lastFunding": "2025-12", "rev": 4.61, "revGrowth": 549.63, "gross": 62.82, "rd": 13.6, "cap": null, "pe": null, "spark": [0.06, 0.71, 4.61, 5.69], "market": "CN", "desc": "上海羲禾科技股份有限公司（Xphor Co., Ltd.），2021 年 5 月成立于上海普陀，专注于硅光集成技术的研发与商业化，主要产品为高性能硅光集成芯片，速率覆盖 400G、800G 及 1.6T，并已拓展 3.2T/6.4T 的 NPO/CPO 收发一体芯片，同时向跨数据中心互连与硅光传感（FMCW 激光雷达）延伸。采用 Fabless 模式（晶圆代工与后道封测全委外），基于 CMOS 工艺做硅光集成芯片设计与测试。据弗若斯特沙利文，2025 年公司硅光集成芯片全球市占率约 13%（收入口径）、出货量口径约 15%，均列全球第二；在独立第三方硅光集成芯片设计厂商中位居全球第一。截至 2026 年 8 月累计出货量突破 1200 万颗，产品已进入国际主要光模块厂商供应链，最终应用于国内外主要云服务厂商的 AI 集群及超大型数据中心。2025 年营收 4.61 亿元（+549.63%）并扭亏为盈（归母净利 1.76 亿元），2026 上半年营收 5.69 亿元已超 2025 全年、归母净利 1.61 亿元，2023—2025 年营收复合增长率 760.34%；截至 2026-08-31 在手订单约 45.51 亿元。2026 年 6 月 30 日科创板 IPO 获受理，2026 年 10 月 14 日通过上市委审议（受理至上会仅 106 天），拟募资 18.3 亿元。", "latestTech": "2026 上半年 1.6T 硅光集成芯片进入批量交付（收入 1.03 亿元、占比 18.04%），NPO/CPO 收发一体芯片实现首批销售，800G 及 1.6T 收入合计占比升至 34.17%", "tech": [{"date": "2026-10", "title": "科创板 IPO 通过上交所上市委审议（2026 年第 52 次会议），受理至上会仅 106 天，保荐机构国泰海通，拟募资 18.3 亿元", "kind": "融资"}, {"date": "2026-09", "title": "上会前夕更新招股书，取消原 6 亿元「补充流动资金」募投项目，募资总额由 24.3 亿元调减至 18.3 亿元", "kind": "融资"}, {"date": "2026-06", "title": "NPO/CPO 收发一体芯片实现首批销售，成为云服务厂商 B 唯一中标的 NPO/CPO 硅光集成芯片合作厂商；3.2T(16×200G)/6.4T(32×200G) 收发一体芯片进入终端验证阶段", "kind": "产品"}, {"date": "2026-H1", "title": "1.6T 硅光集成芯片进入批量交付期，上半年收入 1.03 亿元、占比 18.04%；800G 收入 9179.31 万元、占比 16.13%，高速率产品合计占比升至 34.17%", "kind": "产品"}, {"date": "2026", "title": "突破硅光三大行业难题：渐变型倒锥形光波导将耦合损耗从行业平均 1.5dB 降至 0.5dB 并突破实心光口设计；研制低功耗单波 200Gbps 调制器用于 1.6T 芯片量产；片上复用/解复用器达到 1dB 带宽大于 18nm 的行业领先水平", "kind": "技术"}, {"date": "2025-12", "title": "与腾讯科技（深圳）、腾讯云计算（北京）、海信宽带、上海曼光联合申报的「高性能光集成与光电协同封装技术及产业化」项目获 2025 年度上海市科技进步一等奖，公司为首家完成单位", "kind": "技术"}, {"date": "2025-12", "title": "完成 C 轮融资 3.51 亿元，投后估值 37 亿元", "kind": "融资"}, {"date": "2025", "title": "400G 硅光集成芯片规模量产，产品矩阵拓展至 1.6T 并支持硅光模块规模商用；当年营收 4.61 亿元（+549.63%），扭亏为盈", "kind": "产品"}, {"date": "2024", "title": "搭建完成供应链与运营管理体系，100G/lane DR4 发射芯片实现大规模出货，100G/lane DR8、100G/lane 2×FR4 及 200G/lane DR4 发射芯片实现销售", "kind": "产品"}, {"date": "2023", "title": "100G/lane DR4 发射芯片在插损、调制带宽与调制效率等关键性能指标上实现突破，成为国内少数掌握硅光集成芯片全链条设计能力的团队", "kind": "技术"}], "execChanges": [{"date": "2025-11-26", "event": "羲禾有限完成股份制改革，整体变更为上海羲禾科技股份有限公司"}], "executives": [{"name": "武爱民", "title": "创始人、董事长兼总经理", "role": "board", "shares": "通过上海羲景等五平台合计控制 45.3944% 表决权", "bio": "1980 年生，中国科学院上海微系统与信息技术研究所微电子学与固体电子学博士。2008 年至 2026 年 1 月历任中科院上海微系统所助理研究员、副研究员、研究员，2013—2014 年兼任加州大学伯克利分校访问学者。主导研发的硅基片上光源、大规模硅光集成等技术成果获上海市自然科学一等奖，个人获评上海市优秀学术带头人、国家级创新人才，在硅光集成领域拥有国家发明专利 60 余项。2021 年 5 月创办羲禾有限，历任执行董事，现任公司董事长、总经理，为实际控制人；同时持有控股股东上海羲景 34.68% 出资份额。"}, {"name": "冯大增", "title": "董事、副总经理兼首席技术官", "role": "board", "shares": "持有上海羲景 26.83% 出资份额", "bio": "博士。曾任职于全球最早从事硅光开发的企业之一 Kotura（2013 年被 Mellanox 收购），2006 年即主导研发并量产全球首款基于硅光集成技术的商用可变光衰减器（VOA）芯片——该产品是当时市场上唯一能实现高性能可调光衰减功能的硅光产品，广泛应用于电信网络与数据中心。此后任 Mellanox 高级总监、副总裁（Mellanox 于 2020 年被 NVIDIA 收购）。创始团队成员，为公司核心技术人员，共同承担对赌义务。"}, {"name": "王奕琼", "title": "首席运营官", "role": "management", "shares": "持有上海羲景 22.16% 出资份额", "bio": "博士。曾在早期国际领先的硅光企业 Kotura、Mellanox 任职，主导硅光工艺方向。创始团队成员、公司核心技术人员，共同承担对赌义务；曾担任公司董事，后辞任。"}, {"name": "梁虹", "title": "总工程师", "role": "management", "shares": "持有上海羲景 16.33% 出资份额", "bio": "曾在早期国际领先的硅光企业 Kotura、Mellanox 任职，主导硅光封测方向。创始团队成员、公司核心技术人员，共同承担对赌义务；曾担任公司董事，后辞任。"}, {"name": "吴蒙", "title": "董事会秘书兼投资者关系负责人", "role": "management", "shares": "通过上海晗玚间接持股（上海晗玚持有上海晗矽 67.34% 出资份额）", "bio": "负责公司信息披露与投资者关系工作。同时为申报前 12 个月内新增股东平台上海晗玚的合伙人（出资份额 1%，武爱民持 99%）。"}], "investorsStructured": [{"name": "上海羲景管理咨询合伙企业", "role": "lead", "round": "发起设立", "date": "2021-05", "kind": "other", "note": "控股股东，持股 34.1662%，为创始团队持股平台（武爱民 34.68% / 冯大增 26.83% / 王奕琼 22.16% / 梁虹 16.33%）"}, {"name": "上海晗睿管理咨询合伙企业", "role": "other", "round": "发起设立", "date": "2021-05", "kind": "other", "note": "创始团队持股平台，武爱民控制 6.0118% 表决权"}, {"name": "元禾原点", "role": "lead", "round": "天使轮", "date": "20