: "2025-12", "kind": "gov", "note": "上海张江高科技园区开发股份有限公司（600895.SH）旗下科创基金"}, {"name": "博华资本", "role": "follow", "round": "C 轮", "date": "2025-12", "kind": "pe", "note": "博华投资"}, {"name": "北京电控", "role": "follow", "round": "C 轮", "date": "2025-12", "kind": "gov", "note": "北京电子控股旗下产业投资，与芯动能共同参与"}, {"name": "芯动能", "role": "follow", "round": "C 轮", "date": "2025-12", "kind": "cvc", "note": "芯动能光通、芯动能华景，半导体显示与集成电路产业资本"}, {"name": "普华辰纬", "role": "follow", "round": "C 轮", "date": "2025-12", "kind": "vc"}, {"name": "元禾原点四号", "role": "follow", "round": "C 轮", "date": "2025-12", "kind": "vc", "note": "老股东元禾原点继续加注"}, {"name": "国泰海通", "role": "other", "round": "IPO 保荐", "date": "2026-06", "kind": "other", "note": "保荐机构，其关联方合计间接持股比例小于 1%"}], "funding": [{"date": "2025-12", "round": "C 轮", "amount": "3.51 亿元（投后估值 37 亿元）", "inv": "红杉中国 / 达晨财智 / 新鼎投资 / 金浦投资 / 中芯聚源 / 张江高科 / 元禾原点 / 朗玛峰创投 / 观新光源 / 聚合鹏飞二期 / 麟毅资本 / 普华辰纬 / 舜宇投资 / 芯动能 / 博华资本 / 北京电控 等 30 家主体", "investors": "红杉中国 · 达晨财智 · 新鼎投资 · 金浦投资 · 中芯聚源 · 张江高科 · 元禾原点 · 朗玛峰创投 · 观新光源 · 聚合鹏飞二期 · 麟毅资本 · 普华辰纬 · 舜宇投资 · 芯动能 · 博华资本 · 北京电控"}, {"date": "2025-08", "round": "B 轮", "amount": "1.1 亿元", "inv": "中芯聚源 / 金浦创新 / 金浦金科 / 聚合鹏飞二期 / 元禾原点四号", "investors": "中芯聚源 · 金浦创新 · 金浦金科 · 聚合鹏飞二期 · 元禾原点四号"}, {"date": "2024-09", "round": "B 轮", "amount": "1.26 亿元", "inv": "朗玛八十六号 / 朗玛八十七号 / 深圳达晨 / 杭州达晨 / 观新光源", "investors": "朗玛峰创投（朗玛八十六号、八十七号）· 达晨财智（深圳达晨、杭州达晨）· 观新光源"}, {"date": "2024-05", "round": "B 轮", "amount": "4900 万元", "inv": "光电基金 / 麟毅创投叁号 / 麟毅伍号", "investors": "光电基金 · 麟毅创投叁号 · 麟毅伍号"}, {"date": "2023-05", "round": "B 轮（首批）", "amount": "3000 万元", "inv": "南京交控 / 南京金体", "investors": "南京交控 · 南京金体"}, {"date": "2022-09", "round": "Pre-A 轮", "amount": "未披露", "inv": "朗玛峰创投 / 广州科学城创投 / 普华资本", "investors": "朗玛峰创投 · 广州科学城创投 · 普华资本"}, {"date": "2021-09", "round": "天使轮", "amount": "未披露", "inv": "元禾原点 / 元禾控股 / 舜宇光学旗下产业基金", "investors": "元禾原点 · 元禾控股 · 舜宇光学旗下产业基金"}], "note": "硅光集成芯片国产替代对标：羲禾科技是全球最主要的独立第三方硅光集成芯片设计公司，2025 年全球市占率约 13%（收入口径）位列第二，仅次于中际旭创（约 29%）。国际对标为 Intel（综合平台厂商，硅光业务服务自身生态并对外供货）、Cisco（偏电信）、Marvell（收购 Inphi 布局硅光 DSP 与光互连）、Broadcom（CPO 交换机平台）等。公司核心差异化在于「中立开放的独立第三方」定位——中际旭创、新易盛等光模块龙头自研硅光芯片主要配套自有模块、不对外销售，公司则可面向全市场开放供货，使下游客户无需绑定特定供应商的自研生态，在光模块行业格局分散、头部厂商竞相构建供应链自主能力的背景下，构成保障供应链弹性与技术多样性的关键一环。技术壁垒体现在「全链条」能力：同时打通超低损耗耦合、低功耗高速调制、片上波分复用等七大核心技术并实现规模化交付的厂商全球屈指可数，团队源自 Kotura / Mellanox（英伟达），2006 年即量产全球首款商用硅光 VOA 芯片。风险集中于四方面：① 客户集中度极高（前五大客户收入占比 100%→92.26%，第一大客户占比 90.90%→55.55% 且频繁变动），上交所两轮问询均重点追问业绩可持续性；② 供应商集中，第一大供应商采购占比 54.54%→90.08%，上游晶圆流片资源稀缺；③ 利润未转化为现金，2025 年与 2026 上半年经营性现金流净额仅 269.71 万元、−1375.21 万元，应收账款从 2024 年末 0.66 亿元升至 2026 上半年末 2.99 亿元，存货余额升至 1.46 亿元；④ 产品结构单一（2026 上半年 99.97% 收入来自硅光集成芯片），且龙头光模块厂商（中际旭创 1.6T 硅光良率已达 95%、800G/1.6T 中硅光方案占比超 50%）若大规模自研并改变外采策略，将直接冲击需求。此外创始团队四人共同承担对赌义务但未认定一致行动关系，被上交所问询，控制权认定与股权清晰度需持续关注。"}'::jsonb
)
